import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        int[] l = new int[n];
        for (int i = 0; i < n; i++) {
            l[i] = Integer.parseInt(st.nextToken());
        }
        int frontLen = n / 2;
        int backLen = n - frontLen;
        int[] front = Arrays.copyOfRange(l, 0, frontLen);
        int[] back = Arrays.copyOfRange(l, frontLen, n);

        int frontMask = 1 << frontLen;
        int backMask = 1 << backLen;

        List<Integer> frontSums = new ArrayList<>();
        for (int mask = 0; mask < frontMask; mask++) {
            int total = 0;
            for (int i = 0; i < frontLen; i++) {
                if ((mask & (1 << i)) != 0) {
                    total += front[i];
                }
            }
            frontSums.add(total % m);
        }

        List<Integer> backSums = new ArrayList<>();
        for (int mask = 0; mask < backMask; mask++) {
            int total = 0;
            for (int i = 0; i < backLen; i++) {
                if ((mask & (1 << i)) != 0) {
                    total += back[i];
                }
            }
            backSums.add(total % m);
        }

        Collections.sort(frontSums);
        Collections.sort(backSums);

        int maxModulo = 0;

        for (int s : frontSums) {
            int needed = m - s;
            int candidate = binarySearchFor(backSums, needed);
            maxModulo = Math.max(maxModulo, (s + candidate) % m);
        }

        System.out.println(maxModulo);
    }

    private static int binarySearchFor(List<Integer> list, int x) {
        int left = 0;
        int right = list.size() - 1;
        int res = 0;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (list.get(mid) < x) {
                res = list.get(mid);
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return res;
    }
}
